        sound('cell_charger',COUPLINGS[k+1][1],COUPLINGS[k+1][2],-512)
        evt.SimpleMessage('COUPLING '..({'ONE','TWO','THREE'})[k+1]..": FEED CLOSED.\nThe terminal's locks give. Across the core a coupling's light dies.")
